package com.sstickers.app;
import android.app.*; import android.os.*; import android.content.*; import android.content.res.Configuration; import android.graphics.*; import android.graphics.drawable.GradientDrawable; import android.net.Uri; import android.text.*; import android.view.*; import android.widget.*; import android.util.LruCache; import org.json.*; import java.io.*; import java.util.*;
public class MainActivity extends Activity {
 static class Item {String id,cat,title; Item(JSONObject j)throws JSONException{id=j.getString("id");cat=j.getString("category");title=j.getString("title");}}
 final ArrayList<Item> all=new ArrayList<>(), shown=new ArrayList<>(); final LinkedHashSet<String> fav=new LinkedHashSet<>(), recent=new LinkedHashSet<>();
 final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(12*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}};
 final java.util.concurrent.ExecutorService images=java.util.concurrent.Executors.newFixedThreadPool(2);
 String category="All stickers",query="",mode="All"; boolean dark; int bg,ink,card,muted; LinearLayout root, tabs; GridView grid; TextView count; Adapter adapter; Item pending;
 int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 int color(String s){return Color.parseColor(s);}
 GradientDrawable box(int c,int radius){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(radius));return d;}
 TextView text(String s,int size,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(c);return t;}
 Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(ink);b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b); dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES; bg=color(dark?"#171225":"#F7F3FF"); card=color(dark?"#2B213D":"#FFFFFF");ink=color(dark?"#F5EDFF":"#25163F");muted=color(dark?"#C7B6E1":"#66577E");getWindow().setStatusBarColor(color("#6633CE"));getWindow().setNavigationBarColor(bg); if(Build.VERSION.SDK_INT>=35)getWindow().setDecorFitsSystemWindows(false);
 if(b!=null){category=b.getString("cat","All stickers");mode=b.getString("mode","All");query=b.getString("query","");String saved=b.getString("pending");if(saved!=null)pending=new ItemStub(saved).item();}
 load(); createUi(); refresh();}
 class ItemStub {String id;ItemStub(String s){id=s;}Item item(){try{return new Item(new JSONObject().put("id",id).put("category","").put("title",""));}catch(Exception e){return null;}}}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("cat",category);b.putString("mode",mode);b.putString("query",query);if(pending!=null)b.putString("pending",pending.id);}
 void load(){try(InputStream in=getAssets().open("catalog.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] a=new byte[8192];int n;while((n=in.read(a))!=-1)out.write(a,0,n);JSONArray arr=new JSONArray(out.toString("UTF-8"));for(int i=0;i<arr.length();i++)all.add(new Item(arr.getJSONObject(i)));}catch(Exception e){Toast.makeText(this,"Sticker catalog could not be loaded",Toast.LENGTH_LONG).show();} for(String k:getPreferences(0).getString("fav","").split(","))if(!k.isEmpty())fav.add(k);for(String k:getPreferences(0).getString("recent","").split(","))if(!k.isEmpty())recent.add(k);}
 void save(){getPreferences(0).edit().putString("fav",android.text.TextUtils.join(",",fav)).putString("recent",android.text.TextUtils.join(",",recent)).apply();}
 void createUi(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);root.setPadding(dp(14),dp(12),dp(14),dp(8));setContentView(root);
 if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(14)+bars.left,dp(12)+bars.top,dp(14)+bars.right,dp(8)+bars.bottom);return i;});
 TextView title=text("S Stickers",30,ink);title.setTypeface(null,1);root.addView(title);TextView sub=text("Your expressions, in full colour  •  "+all.size()+" stickers",13,muted);root.addView(sub);
 EditText search=new EditText(this);search.setSingleLine(true);search.setTextColor(ink);search.setHintTextColor(muted);search.setHint("Search stickers and categories");search.setText(query);search.setPadding(dp(14),0,dp(14),0);search.setBackground(box(card,16));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(50));sp.setMargins(0,dp(14),0,dp(8));root.addView(search,sp);
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();refresh();}public void afterTextChanged(Editable e){}});
 tabs=new LinearLayout(this);root.addView(tabs); for(String m:new String[]{"All","Desi","Favorites","Recent"}){Button b=button(m,()->{mode=m;category="All stickers";refresh();});tabs.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));}
 HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout cats=new LinearLayout(this);LinkedHashSet<String> names=new LinkedHashSet<>();names.add("All stickers");for(Item i:all)names.add(i.cat);for(String c:names){Button b=button(c,()->{category=c;if(mode.equals("Desi")&&!c.startsWith("Desi • "))mode="All";refresh();});cats.addView(b);}scroll.addView(cats);root.addView(scroll);
 count=text("",14,muted);count.setPadding(dp(4),dp(7),0,dp(7));root.addView(count);grid=new GridView(this);grid.setNumColumns(3);grid.setVerticalSpacing(dp(8));grid.setHorizontalSpacing(dp(8));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);adapter=new Adapter();grid.setAdapter(adapter);root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));grid.setOnItemClickListener((p,v,pos,id)->preview(shown.get(pos))); }
 void refresh(){if(adapter==null)return;shown.clear();String q=query.trim().toLowerCase(Locale.ROOT);for(Item i:all){if(!category.equals("All stickers")&&!category.equals(i.cat))continue;if(mode.equals("Desi")&&!i.cat.startsWith("Desi • "))continue;if(mode.equals("Favorites")&&!fav.contains(i.id))continue;if(mode.equals("Recent")&&!recent.contains(i.id))continue;if(!(i.title+" "+i.cat).toLowerCase(Locale.ROOT).contains(q))continue;shown.add(i);}if(mode.equals("Recent")){ArrayList<String> order=new ArrayList<>(recent);shown.sort((a,b)->Integer.compare(order.indexOf(b.id),order.indexOf(a.id)));}count.setText(category+"  ·  "+shown.size()+"  ·  "+mode);adapter.notifyDataSetChanged();grid.setSelection(0);}
 Bitmap bitmap(String id,boolean thumb){String key=id+(thumb?"t":"p");Bitmap b=cache.get(key);if(b!=null)return b;try(InputStream in=getAssets().open("stickers/"+id+".png")){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=thumb?4:1;b=BitmapFactory.decodeStream(in,null,o);if(b!=null)cache.put(key,b);return b;}catch(IOException e){return null;}}
 class Adapter extends BaseAdapter{public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){ImageView v=old instanceof ImageView?(ImageView)old:new ImageView(MainActivity.this);v.setLayoutParams(new AbsListView.LayoutParams(-1,dp(115)));v.setPadding(dp(7),dp(7),dp(7),dp(7));v.setScaleType(ImageView.ScaleType.FIT_CENTER);v.setBackground(box(card,18));Item i=shown.get(p);v.setContentDescription(i.title);v.setTag(i.id);v.setImageDrawable(null);Bitmap cached=cache.get(i.id+"t");if(cached!=null)v.setImageBitmap(cached);else images.execute(()->{Bitmap b=bitmap(i.id,true);runOnUiThread(()->{if(i.id.equals(v.getTag()))v.setImageBitmap(b);});});return v;}}
 void preview(Item i){recent.remove(i.id);recent.add(i.id);while(recent.size()>100)recent.remove(recent.iterator().next());save();LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(20),dp(12),dp(20),dp(12));ImageView iv=new ImageView(this);iv.setImageBitmap(bitmap(i.id,false));iv.setScaleType(ImageView.ScaleType.FIT_CENTER);panel.addView(iv,new LinearLayout.LayoutParams(-1,dp(250)));Button f=button(fav.contains(i.id)?"Remove favorite":"Add favorite",()->{});f.setTextColor(color("#702DE8"));f.setOnClickListener(v->{if(!fav.add(i.id))fav.remove(i.id);save();f.setText(fav.contains(i.id)?"Remove favorite":"Add favorite");refresh();});panel.addView(f);Button share=button("Share sticker",()->share(i));share.setTextColor(color("#702DE8"));panel.addView(share);Button download=button("Save PNG",()->download(i));download.setTextColor(color("#702DE8"));panel.addView(download);new AlertDialog.Builder(this).setTitle(i.title).setView(panel).setPositiveButton("Close",null).show();}
 void share(Item i){Uri u=Uri.parse("content://com.sstickers.app.stickers/"+i.id+".png");Intent send=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("Sticker",u));startActivity(Intent.createChooser(send,"Share sticker"));}
 void download(Item i){pending=i;Intent x=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/png").putExtra(Intent.EXTRA_TITLE,"S-Sticker-"+i.id+".png");startActivityForResult(x,12);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==12&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pending!=null){try(InputStream in=getAssets().open("stickers/"+pending.id+".png");OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);Toast.makeText(this,"Sticker saved",Toast.LENGTH_SHORT).show();}catch(IOException e){Toast.makeText(this,"Could not save sticker",Toast.LENGTH_SHORT).show();}}pending=null;}
 protected void onDestroy(){images.shutdownNow();super.onDestroy();}
}
